'use strict';
/*
 * Builds js/bundle.js from the JS sources and stamps content hashes into index.html.
 * Fewer files + cache-busting URLs = far fewer CDN requests per visitor (see vercel.json headers).
 *
 *   npm run bundle              write js/bundle.js and update index.html
 *   node tools/bundle.js --check exit 1 if either is out of date (also run by `npm test`)
 *
 * Edit the sources (js/config.js, js/main.js, …), never js/bundle.js — then run `npm run bundle`.
 */
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const root = path.resolve(__dirname, '..');
// order matters: config first; the tracker before the animation layer so it never waits on it
const SOURCES = ['js/config.js', 'js/meter.js', 'js/main.js', 'js/journey.js', 'js/coin.js'];
const OUT = 'js/bundle.js';
const INDEX = 'index.html';

const read = f => fs.readFileSync(path.join(root, f), 'utf8').replace(/\r\n/g, '\n');
const hash = s => crypto.createHash('sha256').update(s).digest('hex').slice(0, 10);

function build() {
  // each part is wrapped in its own try-block (also a block scope), so an error in one feature
  // can't stop the others — e.g. the tracker keeps working if the animation layer throws
  const parts = SOURCES.map(f =>
    `/* ---- ${f} ---- */\ntry {\n${read(f)}\n} catch (e) { console.error("[toycoin] ${f} failed", e); }\n`);
  const bundle = '/* GENERATED by tools/bundle.js — edit the sources, then run `npm run bundle`. */\n' + parts.join('\n');

  let html = read(INDEX);
  html = html.replace(/css\/style\.css(\?v=[0-9a-f]+)?/g, `css/style.css?v=${hash(read('css/style.css'))}`);
  html = html.replace(/js\/bundle\.js(\?v=[0-9a-f]+)?/g, `js/bundle.js?v=${hash(bundle)}`);
  const icon = fs.readFileSync(path.join(root, 'assets/favicon-32.png')).toString('base64');
  html = html.replace(/(<link rel="icon" type="image\/png" sizes="32x32" href=")[^"]*(")/, `$1data:image/png;base64,${icon}$2`);
  return { bundle, html };
}

function isCurrent() {
  const { bundle, html } = build();
  const cur = f => (fs.existsSync(path.join(root, f)) ? read(f) : null);
  return cur(OUT) === bundle && cur(INDEX) === html;
}

if (require.main === module) {
  if (process.argv.includes('--check')) {
    if (!isCurrent()) { console.error('js/bundle.js or index.html is out of date — run `npm run bundle`'); process.exit(1); }
    console.log('bundle up to date');
  } else {
    const { bundle, html } = build();
    fs.writeFileSync(path.join(root, OUT), bundle);
    fs.writeFileSync(path.join(root, INDEX), html);
    console.log(`wrote ${OUT} (${(bundle.length / 1024).toFixed(1)} KB) and stamped ${INDEX}`);
  }
}

module.exports = { build, isCurrent, SOURCES };
